uint32_t get_buzzer_state_on_count(uint8_t freq, uint8_t pattern, uint8_t count)
{
    buzzer.pitch = freq;
    buzzer.pattern = pattern;
    buzzer.count = count;

    uint32_t togglesCount = 0;

    for (uint32_t timer = 0; timer < 200000; timer++)
    {
        set_buzzer_next_state(&buzzer, timer);

        if (buzzer.state == BUZZER_TOGGLE)
        {
            togglesCount++;
        }
    }

    return togglesCount;
}

void buzzer_output_matches_old_buzzer(void)
{
    std::vector<int> toggles_count;

    for (int i = 0; i < 10; i++)
    {
        for (int j = 0; j < 10; j++)
        {
            for (int k = 0; k < 10; k++)
            {
                toggles_count.push_back(get_buzzer_state_on_count(i, j, k));
            }
        }
    }

    TEST_ASSERT_EQUAL(toggles_count == old_buzzer_toggles_count, true);
}

int main(void)
{
    UNITY_BEGIN();

    RUN_TEST(buzzer_output_matches_old_buzzer);

    return UNITY_END();
}
